        self.multiway_case_identity_contracts_by_edge = {}
        self.multiway_dispatch_static_warnings = []
        self.multiway_dispatch_events = []
        self.multiway_dispatch_warnings = []
        self.multiway_dispatch_rendered_ids = set()
        self.multiway_case_rendered_ids = set()
        self.multiway_case_dropin_satisfied_ids = set()
        self.multiway_dispatch_debug = {}

        self._build_bohdi_emperor_transition_token_consumer_v50()
        self._build_mars_phi_terminal_transaction_consumer_v57()
        self._build_mars_loop_edge_scheduler_v60()
