        self.loop_condition_transaction_inventories = []
        self.loop_condition_transaction_projection_neutral_events = []
        self.loop_condition_transaction_effect_verification_events = []
        self.loop_condition_transaction_unsubstantiated_events = []
        self._active_loop_condition_transaction_ledger_v46x = None

        # v46v: consume SGL v60 return-frontier custody and independently
