        self.no_return_ast_frontier_sites = []
        self.no_return_ast_frontier_sites_by_line = {}
        self.no_return_ast_frontier_consumed = []
        self.no_return_ast_frontier_warnings = []

        # v46z: SGL v61 may prove that an ExecBlock is PAL's synthetic EXIT
